// --- ArenaFrame usage ---
//
// findVar and findVarInFrame themselves do not allocate arena memory.
// However, the .Call-entry wrapper for init_rpcallback (which calls
// compat_getVar which calls findVarInFrame) must declare:
//
//   ArenaFrame _frame;
//
// as its first statement, because init_rpcallback is compiled in the same
// translation unit (rpart_callback.c) as rpart_callback1() and
// rpart_callback2(), which may use R_alloc / ALLOC (arena-backed).
// The ArenaFrame guard is a standard precautionary measure for the entire
// callback subsystem.
//
// Once fake_arena.h is available:
//
//   #include "fake_arena.h"
//   extern "C" SEXP init_rpcallback_wrapper(
//           SEXP rhox, SEXP ny, SEXP nr, SEXP expr1x, SEXP expr2x) {
//       ArenaFrame _frame;   // Invariant 2: frees all R_alloc/ALLOC on exit
//       try {
//           return init_rpcallback(rhox, ny, nr, expr1x, expr2x);
//       } catch (const RError &e) {
//           // Invariant 1: translate C++ exception to a Python-readable message.
//           set_python_error(e.what());
//           return nullptr;   // signals failure to the Python caller
//       }
//   }
//
// Static SEXP singletons (R_NilValue, R_UnboundValue, R_NamesSymbol) survive
// ArenaFrame destruction — they live in the BSS segment, not on the arena.
// Heap SEXPs produced by allocVector / allocMatrix survive too (they use
// std::malloc, not the arena); Python must call free_sexp() or free_sexp_deep()
// after extracting data from returned SEXP values.

